{"code":"import './framer/styles.css';

// Navigation
import NavigationFramerComponent from './framer/navigation';

// Hero Section
import CoreBenefitsFramerComponent from './framer/core-benefits';
import ButtonFramerComponent from './framer/button';

// Brand Logos
import BrandLogosFramerComponent from './framer/brand-logos';

// Stats
import StatsFramerComponent from './framer/stats';

// Steps/How it Works
import StepsFramerComponent from './framer/steps';

// Services/Benefits
import ServiceCardFramerComponent from './framer/service-card';

// Testimonials
import TestimonialFramerComponent from './framer/testimonial';
import VideoTestimonialCardFramerComponent from './framer/video-testimonial-card';

// Team
import TeamCardFramerComponent from './framer/team-card';

// FAQ
import FaqListFramerComponent from './framer/faq-list';

// Footer
import FooterFramerComponent from './framer/navigation/footer';

export default function App() {
  return (
    <div className="flex flex-col items-center gap-3">
      {/* Navigation Bar */}
      <NavigationFramerComponent.Responsive />

      {/* Hero Section */}
      <CoreBenefitsFramerComponent.Responsive
        title={"La tua idea diventa un libro"}
        text={"Mi basta solo qualche indizio, una traccia, al resto penso io. Pensavi fosse così facile?"}
        color={"rgb(255, 254, 245)"}
        sVGCode={"<svg width=\"473\" height=\"449\" viewBox=\"0 0 473 449\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\"> <path fill-rule=\"evenodd\" clip-rule=\"evenodd\" d=\"M0 124.5C0 55.7407 55.7402 0 124.5 0C173.739 0 216.302 28.5845 236.5 70.064C256.698 28.5845 299.261 0 348.5 0C417.26 0 473 55.7407 473 124.5C473 165.466 453.214 201.812 422.677 224.5C453.214 247.188 473 283.534 473 324.5C473 393.259 417.26 449 348.5 449C299.261 449 256.698 420.416 236.5 378.937C216.302 420.416 173.739 449 124.5 449C55.7402 449 0 393.259 0 324.5C0 283.534 19.7861 247.188 50.3232 224.5C19.7861 201.812 0 165.466 0 124.5Z\" fill=\"white\"/> </svg>"}
      />
      <ButtonFramerComponent.Responsive
        link={"https://framer.link/ZMdR1Xm"}
        title={"ORDINA ORA"}
      />

      {/* Brand Logos */}
      <BrandLogosFramerComponent.Responsive
        brandName={"LunarLab"}
        background={"rgb(246, 194, 244)"}
      />

      {/* Stats Section */}
      <StatsFramerComponent.Responsive
        title={"Libri aziendali"}
        value={40}
        suffix={"+"}
      />

      {/* How it Works / Steps */}
      <StepsFramerComponent.Responsive
        step1Title={"Raccontami la tua idea"}
        step2Title={"L'Artigiano si mette al lavoro"}
        step3Title={"Creazione, disegni e correzione"}
        step4Title={"Impaginazione, stampa e consegna"}
        step1Details={"Il primo step è fondamentale. Decidi lo stile narrativo. Poi mi servono delle info generiche sul libro che vuoi realizzare. La trama, i personaggi e dettagli che vuoi inserire. E' sufficiente!"}
        step2Details={"In questa fase preparo un progetto partendo dalle indicazioni, descrivo meglio i personaggi, le interazioni con gli altri, i luoghi e divido la storia in capitoli. Ora il lavoro può passare alla fase di creazione."}
        step3Details={"Questa è la fase più lunga, in cui si crea la storia, si passano le scene agli illustratori e poi si manda il tutto al correttore di bozze: un lavorone, ma stupendo! La storia è nata!"}
        step4Details={"Altri passaggi fondamentali, l'impaginazione editoriale e l'invio del manoscritto al tipografo. Al ricevimento, si prepara il pacco e te lo spedisco a casa tua!"}
      />

      {/* Services/Benefits Section */}
      <ServiceCardFramerComponent.Responsive
        title={"Servizio su misura"}
        description={"Ogni libro è unico, creato secondo le tue esigenze e desideri."}
        iconSVG={"<svg width=\"40\" height=\"40\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\"><circle cx=\"20\" cy=\"20\" r=\"20\" fill=\"#F6C2F4\"/><path d=\"M20 10v20M10 20h20\" stroke=\"#E95935\" stroke-width=\"2\"/></svg>"}
      />

      {/* Testimonials Section */}
      <TestimonialFramerComponent.Responsive
        name1={"Tobias Green"}
        direction={"Vertical"}
        background={"rgb(240, 159, 168)"}
        clientInfo={"Founder, GreenSpark Innovations"}
        testimonial={"\"Working with this team was a dream. Super organized, wildly creative, and just fun to talk to. They totally got our brand from day one.\""}
      />
      <VideoTestimonialCardFramerComponent.Responsive
        background={"rgb(246, 194, 244)"}
        clientName={"Libro regalo"}
        youtubeLink={"https://youtu.be/Ly1auHs_ofo"}
        clientDetails={"Consigli"}
      />

      {/* Team Section */}
      <TeamCardFramerComponent.Responsive
        role={"CEO, Direzione"}
        xLink={"x.com"}
        lastName={"Cerba"}
        firstName={"Max"}
        background={"rgb(250, 224, 190)"}
        linkedinLink={"linkedin.com"}
      />

      {/* FAQ Section */}
      <FaqListFramerComponent.Responsive />

      {/* Final Call to Action */}
      <ButtonFramerComponent.Responsive
        link={"https://framer.link/ZMdR1Xm"}
        title={"ORDINA ORA"}
      />

      {/* Footer */}
      <FooterFramerComponent.Responsive />
    </div>
  );
}
"}

