    />
    <StepsFramerComponent.Responsive
      step1Title={"Raccontami la tua idea"}
      step2Title={"L'Artigiano si mette al lavoro"}
      step3Title={"Creazione, disegni e correzione"}
      step4Title={"Impaginazione, stampa e consegna"}
