import './framer/styles.css';

import NavigationFramerComponent from './framer/navigation';
import CoreBenefitsFramerComponent from './framer/core-benefits';
import BrandLogosFramerComponent from './framer/brand-logos';
import StatsFramerComponent from './framer/stats';
import StepsFramerComponent from './framer/steps';
